+++ b/hadoop-tools/hadoop-archives/src/test/java/org/apache/hadoop/tools/TestHadoopArchives.java
@@ -444,7 +444,7 @@ public void testReadFileContent() throws Exception {
       int read; 
       while (true) {
         read = fsdis.read(buffer, readIntoBuffer, buffer.length - readIntoBuffer);
-        if (read < 0) {
+        if (read <= 0) {
           // end of stream:
           if (readIntoBuffer > 0) {
             baos.write(buffer, 0, readIntoBuffer);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the condition in the while loop that checked for the end of the stream. The original condition `if (read < 0)` did not account for the scenario where the `read` method returned zero, which indicates that no bytes were read but the end of the stream had not yet been reached. This could lead to the loop terminating prematurely, causing the test to timeout as it would not process all available data correctly.

        Commit message:
        HADOOP-13798. TestHadoopArchives times out.  

        Patch:

   private static byte[] readAllWithBuffer(FSDataInputStream fsdis, boolean close)
       throws IOException {
     try {
       final int available = fsdis.available();
       final byte[] buffer;
       final ByteArrayOutputStream baos;
       if (available < 0) {
         buffer = new byte[1024];
         baos = new ByteArrayOutputStream(buffer.length * 2);
       } else {
         buffer = new byte[available];
         baos = new ByteArrayOutputStream(available);
       }
       int readIntoBuffer = 0;
       int read; 
       while (true) {
         read = fsdis.read(buffer, readIntoBuffer, buffer.length - readIntoBuffer);
-        if (read < 0) {
+        if (read <= 0) {
           // end of stream:
           if (readIntoBuffer > 0) {
             baos.write(buffer, 0, readIntoBuffer);
           }
           return baos.toByteArray();
         } else {
           readIntoBuffer += read;
           if (readIntoBuffer == buffer.length) {
             // buffer is full, need to clean the buffer.
             // drop the buffered data to baos:
             baos.write(buffer);
             // reset the counter to start reading to the buffer beginning:
             readIntoBuffer = 0;
           } else if (readIntoBuffer > buffer.length) {
             throw new IOException("Read more than the buffer length: "
                 + readIntoBuffer + ", buffer length = " + buffer.length);
           }
         }
       }
     } finally {
       if (close) {
         fsdis.close();
       }
     }
   }



